<?php
require_once __DIR__.'/config/app.php'; $user=require_role(['admin']); $EMS_WITH_SIDEBAR=true;
require_once __DIR__.'/includes/layout.php'; page_header('Attendance',$user); echo flash();

if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)$_POST['employee_id'];$date=$_POST['attendance_date'];$status=$_POST['status'];$notes=trim($_POST['notes']);$s=$pdo->prepare('INSERT INTO attendance(employee_id,attendance_date,status,notes) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE status=VALUES(status),notes=VALUES(notes)');$s->execute([$id,$date,$status,$notes]);flash('Attendance recorded.');}
$employees=$pdo->query('SELECT id,name FROM employees ORDER BY name')->fetchAll();$rows=$pdo->query('SELECT a.*,e.name FROM attendance a JOIN employees e ON e.id=a.employee_id ORDER BY attendance_date DESC,e.name')->fetchAll();
?>
<div class="card mb-4"><div class="card-body"><form method="post" class="row g-2"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><div class="col-md-3"><select class="form-select" name="employee_id" required><option value="">Select employee</option><?php foreach($employees as$e):?><option value="<?=$e['id']?>"><?=htmlspecialchars($e['name'])?></option><?php endforeach?></select></div><div class="col-md-3"><input class="form-control" type="date" name="attendance_date" value="<?=date('Y-m-d')?>" required></div><div class="col-md-2"><select class="form-select" name="status"><option value="present">Present</option><option value="absent">Absent</option><option value="late">Late</option><option value="leave">Leave</option></select></div><div class="col-md-3"><input class="form-control" name="notes" placeholder="Notes"></div><div class="col-md-1"><button class="btn btn-primary w-100">Save</button></div></form></div></div>
<div class="table-responsive"><table class="table table-striped"><thead><tr><th>Employee</th><th>Date</th><th>Status</th><th>Notes</th></tr></thead><tbody><?php foreach($rows as$r):?><tr><td><?=htmlspecialchars($r['name'])?></td><td><?=htmlspecialchars($r['attendance_date'])?></td><td><?=ucfirst(htmlspecialchars($r['status']))?></td><td><?=htmlspecialchars($r['notes'])?></td></tr><?php endforeach?></tbody></table></div>
<?php page_footer(); ?>
